import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./BusBook.css";

const busOptions = [
  { id: 1, name: "Shivshahi Express", company: "Shivshahi", price: 500, image: "data:image/jpeg;base64," },
  { id: 2, name: "Balaji AC Sleeper", company: "Balaji", price: 900, image: "data:image/jpeg;base64," },
  { id: 3, name: "Force Traveller Mini", company: "Force", price: 600, image: "data:image/jpeg;base64," },
  { id: 4, name: "Sai Travellers", company: "Travellers", price: 700, image: "https://s3-ap-southeast-1.amazonaws.com/rbplus/BusImage/Domestic/20552_16_4.png" },
  { id: 5, name: "Shivneri Deluxe", company: "Shivshahi", price: 750, image: "data:image/jpeg;base64," },
  { id: 6, name: "Balaji Luxury Coach", company: "Balaji", price: 1100, image: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRkyYBZIsII60lTMplGmOXDhYMy-NnWwmSJrg&s" },
  { id: 7, name: "Force Tempo Traveller", company: "Force", price: 550, image: "data:image/jpeg;base64," },
  { id: 8, name: "Ganesh Travellers", company: "Travellers", price: 650, image: "data:image/jpeg;base64," },
  { id: 9, name: "Shivshahi Night Rider", company: "Shivshahi", price: 800, image: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRHzPnkreiHPrJpGcRY8TZQRivFeqJUPnifyw&s" },
  { id: 10, name: "Balaji Express", company: "Balaji", price: 850, image: "data:image/jpeg;base64," },
  { id: 11, name: "Force City Traveller", company: "Force", price: 580, image: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQZYI5F4gDaV9KkhzYz_BWpEYeHyS8UUoiaIg&s" },
  { id: 12, name: "Om Travellers", company: "Travellers", price: 720, image: "data:image/jpeg;base64," },
  { id: 13, name: "Shivshahi Super Fast", company: "Shivshahi", price: 780, image: "data:image/jpeg;base64," },
  { id: 14, name: "Balaji Premium", company: "Balaji", price: 1000, image: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSaYhvUKZLSXkd0RjDwNkbbDfGPFmfKBBV5dA&s" },
  { id: 15, name: "Force Deluxe Traveller", company: "Force", price: 620, image: "data:image/jpeg;base64," },
];

const BusRental = () => {
  const navigate = useNavigate();

  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("All");
  const [sort, setSort] = useState("default");

  const companies = ["All", "Shivshahi", "Balaji", "Force", "Travellers"];

  let filtered = busOptions.filter(
    (bus) =>
      (filter === "All" || bus.company === filter) &&
      bus.name.toLowerCase().includes(search.toLowerCase())
  );

  if (sort === "low") {
    filtered.sort((a, b) => a.price - b.price);
  }

  return (
    <div className="bus-book-page">
      <h1>🚌 Rent a Bus</h1>

      {/* Search */}
      <input
        type="text"
        placeholder="Search bus..."
        className="search-input"
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />

      {/* Filters */}
      <div className="filter-buttons">
        {companies.map((c) => (
          <button
            key={c}
            className={`filter-btn ${filter === c ? "active-filter" : ""}`}
            onClick={() => setFilter(c)}
          >
            {c === "Shivshahi" && "🟥"}
            {c === "Balaji" && "🟨"}
            {c === "Force" && "🚐"}
            {c === "Travellers" && "🚌"}
            {c === "All" && "🌐"} {c}
          </button>
        ))}
      </div>

      {/* Sort */}
      <div className="sort-box">
        <label>Sort by Price: </label>
        <select onChange={(e) => setSort(e.target.value)}>
          <option value="default">Default</option>
          <option value="low">Low → High</option>
        </select>
      </div>

      {/* Cards */}
      <div className="card-grid">
        {filtered.map((bus) => (
          <div className="card" key={bus.id}>
            <img src={bus.image} alt={bus.name} className="card-image" />

            <div className="card-info">
              <h3>{bus.name}</h3>
              <p>{bus.company}</p>
              <p>₹{bus.price} / km</p>

              <button
                className="book-btn"
                onClick={() => navigate("/book", { state: bus })}
              >
                Book Now
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* Back */}
      <button className="back-btn" onClick={() => navigate(-1)}>
        ⬅️ Back
      </button>
    </div>
  );
};

export default BusRental;